import styled from "styled-components";


export const Title = styled.div`
  color: #ffffff;
  font-size: 12px;
  line-height: 16px;
  font-weight: 750;
  letter-spacing: 1.4px;
`;

export const TextFieldWrapper = styled.div`
  display: flex;
  color: white !important;
  width: 100%;
`;
